<style>
.course-detail{max-width:1180px;margin:auto;padding:104px 24px 65px}.back{display:inline-flex;align-items:center;gap:8px;color:#0f766e;font-weight:700;margin-bottom:20px}.hero{background:linear-gradient(130deg,#0f766e,#115e59 60%,#0f172a);color:#fff;border-radius:26px;padding:42px;display:grid;grid-template-columns:1fr auto;gap:28px;overflow:hidden;position:relative}.hero:after{content:'汉语';position:absolute;right:25px;bottom:-42px;font-size:11rem;font-weight:900;color:#ffffff12;pointer-events:none}.level{display:inline-block;background:#ffffff20;border:1px solid #ffffff38;border-radius:99px;padding:7px 13px;font-weight:800;font-size:.85rem}.hero h1{font-size:clamp(2rem,5vw,3.1rem);margin:15px 0 12px}.hero p{max-width:680px;line-height:1.7;color:#d1fae5;font-size:1.05rem}.metrics{display:flex;flex-wrap:wrap;gap:12px;margin-top:22px}.metric{background:#ffffff14;border:1px solid #ffffff21;border-radius:12px;padding:10px 13px;font-size:.88rem}.hero-mark{width:160px;height:160px;display:grid;place-items:center;border:1px solid #ffffff25;border-radius:50%;font-size:5rem;background:#ffffff0d;z-index:1}.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:28px;margin-top:28px}.section{background:#fff;border:1px solid #e2e8f0;border-radius:20px;padding:28px;margin-bottom:20px;box-shadow:0 7px 22px rgba(15,23,42,.05)}.section h2{margin:0 0 15px;color:#102a56;font-size:1.35rem}.outcomes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.outcome{padding:14px;border-radius:12px;background:#f0fdfa;color:#134e4a;font-size:.92rem}.outcome b{display:block;color:#0f766e;margin-bottom:3px}.curriculum{padding:0;margin:0;list-style:none}.curriculum li{display:flex;align-items:center;gap:13px;border-top:1px solid #eef2f7;padding:15px 0;color:#334155}.lesson-num{width:29px;height:29px;border-radius:50%;background:#ecfdf5;color:#047857;display:grid;place-items:center;font-size:.78rem;font-weight:800;flex:none}.lesson-title{font-weight:700}.lesson-meta{margin-left:auto;color:#94a3b8;font-size:.82rem;white-space:nowrap}.buy-card{position:sticky;top:25px;background:#fff;border:1px solid #dbeafe;border-radius:20px;padding:24px;box-shadow:0 12px 30px rgba(15,23,42,.1)}.buy-card h3{margin:0 0 12px;color:#102a56}.price{font-size:2.1rem;font-weight:900;color:#0f766e;margin:8px 0}.old{color:#94a3b8;text-decoration:line-through;font-size:.92rem}.buy-card .btn{display:block;width:100%;text-align:center;margin:18px 0 13px}.safe{font-size:.83rem;color:#64748b;line-height:1.55}.safe span{color:#059669;font-weight:800}.pay-panel{display:none;margin-top:18px;border-top:1px dashed #cbd5e1;padding-top:20px;text-align:center}.pay-panel.show{display:block}.qr{width:min(100%,260px);border-radius:14px;border:1px solid #e2e8f0}.pay-code{font-family:ui-monospace,monospace;background:#f8fafc;border-radius:8px;padding:8px;display:inline-block;color:#0f766e;font-weight:800}.status{font-size:.9rem;color:#64748b}.skeleton{min-height:550px;background:linear-gradient(90deg,#f1f5f9,#f8fafc,#f1f5f9);border-radius:25px}@media(max-width:850px){.layout{grid-template-columns:1fr}.buy-card{position:static}.hero{grid-template-columns:1fr}.hero-mark{display:none}}@media(max-width:560px){.course-detail{padding:85px 15px 35px}.hero{padding:28px 22px}.outcomes{grid-template-columns:1fr}.lesson-meta{display:none}.section{padding:20px}}
</style>
</head>
<body>
<?php include 'sidebar.php'; ?>
<main class="course-detail"><a class="back" href="courses.php">← Quay lại danh sách khóa học</a><div id="app" class="skeleton"></div></main>
<script>
const slug=new URLSearchParams(location.search).get('slug');let course,csrfToken,pollTimer;
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ';
const content={
  1:{icon:'你',subtitle:'Xây nền phát âm, chữ Hán và giao tiếp đầu tiên.',time:'30 bài · 8 tuần',words:'150 từ vựng',out:['Nắm vững Pinyin','Tự giới thiệu bản thân','Giao tiếp tình huống cơ bản','Sẵn sàng học HSK 2']},
  2:{icon:'好',subtitle:'Mở rộng phản xạ giao tiếp và vốn từ sử dụng hằng ngày.',time:'38 bài · 10 tuần',words:'300 từ vựng',out:['Mô tả người và sự việc','Hỏi – đáp tự nhiên','Dùng cấu trúc so sánh','Làm quen đề HSK 2']},
  3:{icon:'学',subtitle:'Hoàn thiện trình độ sơ cấp với bốn kỹ năng và luyện thi.',time:'45 bài · 12 tuần',words:'600 từ vựng',out:['Viết đoạn văn ngắn','Nghe hội thoại dài hơn','Đọc hiểu theo ngữ cảnh','Thi thử HSK 3']},
  4:{icon:'中',subtitle:'Tăng tốc giao tiếp trung cấp, đọc hiểu và viết tiếng Trung.',time:'48 bài · 14 tuần',words:'1.200 từ vựng',out:['Dùng câu phức tự nhiên','Đọc bài viết thực tế','Giao tiếp chủ đề công việc','Luyện thi HSK 4']},
  5:{icon:'文',subtitle:'Chinh phục tiếng Trung nâng cao cho học tập và công việc.',time:'50 bài · 16 tuần',words:'2.500 từ vựng',out:['Đọc báo và bài luận','Viết bài theo chủ đề','Nâng phản xạ diễn đạt','Luyện đề HSK 5']},
  6:{icon:'语',subtitle:'Lộ trình chuyên sâu làm chủ đọc hiểu và chiến thuật HSK 6.',time:'60 bài · 20 tuần',words:'5.000+ từ vựng',out:['Phân tích văn bản dài','Tóm tắt và diễn đạt sâu','Làm chủ dạng đề khó','Luyện thi HSK 6']}
};
const reference={1:'2.000.000đ',2:'2.400.000đ',3:'3.000.000đ',4:'4.500.000đ',5:'4.800.000đ',6:'6.000.000đ'};
async function csrf(){if(!csrfToken)csrfToken=(await fetch('api.php?action=get_csrf_token')).json().then(x=>x.csrf_token);return csrfToken}
function esc(s){const e=document.createElement('span');e.textContent=s||'';return e.innerHTML}
function render(){const info=content[course.hsk_level]||content[1];const lessons=(course.lessons||[]);document.getElementById('app').className='';document.getElementById('app').innerHTML=`
<header class="hero"><div><span class="level">KHÓA HỌC HSK ${course.hsk_level||''}</span><h1>${esc(course.title)}</h1><p>${esc(course.description||course.short_description||info.subtitle)}</p><div class="metrics"><span class="metric">📚 ${lessons.length||course.lesson_count||0} bài học</span><span class="metric">⏱ ${info.time}</span><span class="metric">🈶 ${info.words}</span><span class="metric">♾️ Học mọi lúc</span></div></div><div class="hero-mark">${info.icon}</div></header>
<div class="layout"><div><section class="section"><h2>Sau khóa học bạn có thể</h2><div class="outcomes">${info.out.map((x,i)=>`<div class="outcome"><b>✓ Mục tiêu ${i+1}</b>${x}</div>`).join('')}</div></section><section class="section"><h2>Nội dung khóa học</h2><ul class="curriculum">${lessons.length?lessons.map((l,i)=>`<li><span class="lesson-num">${i+1}</span><span class="lesson-title">${esc(l.title)}</span><span class="lesson-meta">${l.vocab_count||'10'} từ · 30 phút</span></li>`).join(''):'<li>Giáo trình đang được cập nhật.</li>'}</ul></section></div><aside><div class="buy-card"><h3>Đăng ký khóa học</h3><div class="price">${money(course.price)}</div><div class="old">Giá tham khảo ${reference[course.hsk_level]||''}</div>${course.enrolled?'<a class="btn btn--primary" href="learn_course.php?slug='+encodeURIComponent(course.slug)+'">Vào khu vực học</a>':'<button class="btn btn--primary" id="buy">Mua khóa học ngay</button>'}<p class="safe"><span>✓</span> Thanh toán qua QR MB Bank<br><span>✓</span> Cấp quyền học sau khi thanh toán<br><span>✓</span> Nhận hóa đơn điện tử qua email</p><div class="pay-panel" id="pay"></div></div></aside></div>`;if(!course.enrolled)document.getElementById('buy').onclick=createOrder}
async function createOrder(){let token=await csrf();let r=await fetch('api.php?action=create_order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({course_id:course.id,csrf_token:token})}).then(x=>x.json()).catch(()=>({success:false,message:'Không kết nối được máy chủ.'}));if(!r.success){alert(r.message||'Không thể tạo đơn hàng.');if((r.message||'').includes('đăng nhập'))location.href='login.php';return}showPayment(r.order)}
function showPayment(order){let p=document.getElementById('pay');p.classList.add('show');p.innerHTML=`<h3>Quét QR để thanh toán</h3><p>Chuyển đúng <b>${money(order.amount)}</b></p>${order.qr_url?`<img class="qr" src="${order.qr_url}" alt="QR thanh toán">`:'<p class="status">Chưa cấu hình QR nhận tiền.</p>'}<p class="status">Nội dung chuyển khoản:<br><span class="pay-code">${order.order_code}</span></p><p class="status" id="status">Đang chờ xác nhận thanh toán...</p>`;p.scrollIntoView({behavior:'smooth',block:'center'});checkPayment(order.id)}
function checkPayment(id){clearInterval(pollTimer);pollTimer=setInterval(async()=>{let r=await fetch('api.php?action=get_order&id='+id).then(x=>x.json()).catch(()=>null);if(!r||!r.success)return;let el=document.getElementById('status');if(r.order.status==='paid'){clearInterval(pollTimer);el.innerHTML='<b style="color:#047857">Thanh toán thành công! Đang mở khóa học...</b>';setTimeout(()=>location.reload(),1200)}else if(r.order.status!=='pending'){clearInterval(pollTimer);el.textContent='Đơn hàng đã '+r.order.status+'.'}},5000)}
fetch('api.php?action=get_course&slug='+encodeURIComponent(slug||'')).then(x=>x.json()).then(r=>{if(!r.success){document.getElementById('app').className='section';document.getElementById('app').textContent=r.message||'Không tìm thấy khóa học.';return}course=r.course;render()}).catch(()=>{document.getElementById('app').className='section';document.getElementById('app').textContent='Không thể tải khóa học. Hãy thử lại.'});
</script></body></html>
